{"title": "Vega Pareto Curve: Top Error Rules & Cumulative %", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": {
      "%context%": true,
      "%timefield%": "@timestamp",
      "index": "xml-insight-testcases-v1*",
      "body": {
        "size": 0,
        "aggs": {
          "rules": {
            "terms": {
              "field": "error_mapping.rule_id",
              "size": 15
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.rules.buckets"
    }
  },
  "transform": [
    {
      "window": [
        {
          "op": "sum",
          "field": "doc_count",
          "as": "cum_count"
        }
      ],
      "frame": [
        null,
        0
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "doc_count",
          "as": "total_count"
        }
      ]
    },
    {
      "calculate": "round(datum.cum_count / datum.total_count * 1000) / 10",
      "as": "cum_pct"
    }
  ],
  "resolve": {
    "scale": {
      "y": "independent"
    }
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "color": "#4f46e5",
        "cornerRadiusTopLeft": 4,
        "cornerRadiusTopRight": 4
      },
      "encoding": {
        "x": {
          "field": "key",
          "type": "nominal",
          "sort": null,
          "title": "Error Mapping Rule ID",
          "axis": {
            "labelAngle": -15
          }
        },
        "y": {
          "field": "doc_count",
          "type": "quantitative",
          "title": "Failures (Count)"
        }
      }
    },
    {
      "mark": {
        "type": "line",
        "color": "#dc2626",
        "strokeWidth": 3,
        "point": {
          "filled": true,
          "size": 70,
          "color": "#dc2626"
        }
      },
      "encoding": {
        "x": {
          "field": "key",
          "type": "nominal",
          "sort": null
        },
        "y": {
          "field": "cum_pct",
          "type": "quantitative",
          "title": "Cumulative Share (%)",
          "scale": {
            "domain": [
              0,
              105
            ]
          },
          "axis": {
            "orient": "right",
            "titleColor": "#dc2626"
          }
        }
      }
    }
  ]
}"}}

{"title": "Vega Campaign x Bench Health Swimlane Matrix", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": {
      "%context%": true,
      "%timefield%": "@timestamp",
      "index": "xml-insight-runs-v1*",
      "body": {
        "size": 0,
        "aggs": {
          "by_campaign": {
            "terms": {
              "field": "campaign.id",
              "size": 10,
              "order": {
                "_key": "asc"
              }
            },
            "aggs": {
              "by_bench": {
                "terms": {
                  "field": "test_bench.id",
                  "size": 10,
                  "order": {
                    "_key": "asc"
                  }
                },
                "aggs": {
                  "failed_tc_sum": {
                    "sum": {
                      "field": "regular_tc_failed"
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.by_campaign.buckets"
    }
  },
  "transform": [
    {
      "flatten": [
        "by_bench.buckets"
      ],
      "as": [
        "b"
      ]
    },
    {
      "calculate": "datum.key",
      "as": "campaign"
    },
    {
      "calculate": "datum.b.key",
      "as": "bench"
    },
    {
      "calculate": "datum.b.doc_count",
      "as": "runs"
    },
    {
      "calculate": "datum.b.failed_tc_sum.value",
      "as": "failed_tcs"
    },
    {
      "calculate": "datum.failed_tcs == 0 ? 'HEALTHY (0 fail)' : datum.failed_tcs + ' Failed TCs'",
      "as": "label"
    },
    {
      "calculate": "datum.failed_tcs == 0 ? '0_HEALTHY' : (datum.failed_tcs <= 3 ? '1_DEGRADED' : '2_CRITICAL')",
      "as": "status"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "rect",
        "cornerRadius": 6,
        "stroke": "#ffffff",
        "strokeWidth": 3
      },
      "encoding": {
        "x": {
          "field": "campaign",
          "type": "ordinal",
          "title": "Nightly Campaign",
          "axis": {
            "labelAngle": 0
          }
        },
        "y": {
          "field": "bench",
          "type": "ordinal",
          "title": "Test Bench"
        },
        "color": {
          "field": "status",
          "type": "nominal",
          "title": "Health Tier",
          "scale": {
            "domain": [
              "0_HEALTHY",
              "1_DEGRADED",
              "2_CRITICAL"
            ],
            "range": [
              "#10b981",
              "#f59e0b",
              "#ef4444"
            ]
          }
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "fontWeight": "bold",
        "color": "#ffffff",
        "fontSize": 12
      },
      "encoding": {
        "x": {
          "field": "campaign",
          "type": "ordinal"
        },
        "y": {
          "field": "bench",
          "type": "ordinal"
        },
        "text": {
          "field": "label",
          "type": "nominal"
        }
      }
    }
  ]
}"}}

{"title": "Vega Parallel Coordinates Flow: Bench -> Version -> Suite -> Category -> Owner", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": {
      "%context%": true,
      "%timefield%": "@timestamp",
      "index": "xml-insight-testcases-v1*",
      "body": {
        "size": 200,
        "_source": [
          "test_bench.id",
          "software.version",
          "suite.name",
          "error_mapping.category",
          "error_mapping.owner"
        ]
      }
    },
    "format": {
      "property": "hits.hits"
    }
  },
  "transform": [
    {
      "filter": "datum._source.error_mapping && datum._source.error_mapping.category"
    },
    {
      "calculate": "datum._source.test_bench.id",
      "as": "1_Bench"
    },
    {
      "calculate": "datum._source.software.version",
      "as": "2_Version"
    },
    {
      "calculate": "datum._source.suite.name",
      "as": "3_Suite"
    },
    {
      "calculate": "datum._source.error_mapping.category",
      "as": "4_Category"
    },
    {
      "calculate": "datum._source.error_mapping.owner",
      "as": "5_Owner"
    },
    {
      "window": [
        {
          "op": "row_number",
          "as": "id"
        }
      ]
    },
    {
      "fold": [
        "1_Bench",
        "2_Version",
        "3_Suite",
        "4_Category",
        "5_Owner"
      ],
      "as": [
        "Stage",
        "Value"
      ]
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "line",
        "opacity": 0.35,
        "strokeWidth": 2.5
      },
      "encoding": {
        "x": {
          "field": "Stage",
          "type": "ordinal",
          "title": "Diagnostic Dimension Flow",
          "axis": {
            "labelAngle": 0
          }
        },
        "y": {
          "field": "Value",
          "type": "nominal",
          "title": "Dimension Value"
        },
        "color": {
          "field": "4_Category",
          "type": "nominal",
          "title": "Category"
        },
        "detail": {
          "field": "id",
          "type": "nominal"
        }
      }
    },
    {
      "mark": {
        "type": "circle",
        "size": 90,
        "opacity": 0.9
      },
      "encoding": {
        "x": {
          "field": "Stage",
          "type": "ordinal"
        },
        "y": {
          "field": "Value",
          "type": "nominal"
        },
        "color": {
          "field": "4_Category",
          "type": "nominal"
        }
      }
    }
  ]
}"}}

{"title": "Interactive Vega Explorer (Built-In HTML Radio Buttons, Dropdown & Slider)", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "autosize": "none",
  "width": 360,
  "height": 100,
  "params": [
    {
      "name": "OwnerFilter",
      "value": "ALL",
      "bind": {
        "input": "radio",
        "options": [
          "ALL",
          "APPLICATION",
          "PLATFORM",
          "TEST_INFRASTRUCTURE"
        ],
        "name": "Owner (Radio): "
      }
    },
    {
      "name": "SeveritySelect",
      "value": "ALL",
      "bind": {
        "input": "select",
        "options": [
          "ALL",
          "CRITICAL",
          "HIGH",
          "MEDIUM",
          "LOW"
        ],
        "name": "Severity (Dropdown): "
      }
    },
    {
      "name": "MinFaults",
      "value": 1,
      "bind": {
        "input": "range",
        "min": 1,
        "max": 3,
        "step": 1,
        "name": "Min Faults (Slider): "
      }
    }
  ],
  "data": {
    "url": {
      "%context%": true,
      "%timefield%": "@timestamp",
      "index": "xml-insight-testcases-v1*",
      "body": {
        "size": 300,
        "_source": [
          "test_bench.id",
          "suite.name",
          "test_case.name",
          "software.version",
          "fault_count",
          "error_mapping"
        ]
      }
    },
    "format": {
      "property": "hits.hits"
    }
  },
  "transform": [
    {
      "filter": "datum._source.error_mapping && datum._source.error_mapping.category"
    },
    {
      "calculate": "datum._source.test_case.name",
      "as": "testcase"
    },
    {
      "calculate": "datum._source.error_mapping.category",
      "as": "category"
    },
    {
      "calculate": "datum._source.error_mapping.owner",
      "as": "owner"
    },
    {
      "calculate": "datum._source.error_mapping.severity",
      "as": "severity"
    },
    {
      "calculate": "datum._source.fault_count || 1",
      "as": "faults"
    },
    {
      "filter": "(OwnerFilter == 'ALL' || datum.owner == OwnerFilter) && (SeveritySelect == 'ALL' || datum.severity == SeveritySelect) && datum.faults >= MinFaults"
    },
    {
      "aggregate": [
        {
          "op": "count",
          "as": "failures"
        }
      ],
      "groupby": [
        "testcase",
        "category",
        "severity",
        "owner"
      ]
    }
  ],
  "mark": {
    "type": "bar",
    "cornerRadiusEnd": 4,
    "stroke": "#ffffff",
    "strokeWidth": 1
  },
  "encoding": {
    "y": {
      "field": "testcase",
      "type": "nominal",
      "sort": "-x",
      "title": "TestCase"
    },
    "x": {
      "field": "failures",
      "type": "quantitative",
      "title": "Matching Failures"
    },
    "color": {
      "field": "severity",
      "type": "nominal",
      "title": "Severity",
      "scale": {
        "domain": [
          "CRITICAL",
          "HIGH",
          "MEDIUM",
          "LOW"
        ],
        "range": [
          "#dc2626",
          "#f97316",
          "#eab308",
          "#10b981"
        ]
      }
    }
  },
  "padding": {
    "left": 135,
    "right": 85,
    "top": 5,
    "bottom": 28
  }
}"}}

