elements.expression:
essql query="SELECT \"error_mapping.category\" AS Category, \"error_mapping.rule_id\" AS Rule_ID, \"error_mapping.root_cause\" AS Root_Cause, \"error_mapping.owner\" AS Owner, COUNT(*) AS Failures FROM \"xml-insight-testcases-v1*\" WHERE phase = 'suite' AND \"error_mapping.category\" IS NOT NULL GROUP BY \"error_mapping.category\", \"error_mapping.rule_id\", \"error_mapping.root_cause\", \"error_mapping.owner\" ORDER BY Failures DESC"
| table perPage=8 font={font size=13 family="Inter, sans-serif" color="#f8fafc" align="left"}
| render css=".canvasRenderEl { background: #1e293b; border: 1px solid #475569; border-radius: 14px; padding: 16px; color: #f8fafc; } .canvasRenderEl th { background: #312e81 !important; color: #38bdf8 !important; font-weight: 800; padding: 10px !important; } .canvasRenderEl td { color: #f1f5f9 !important; padding: 8px 10px !important; border-bottom: 1px solid #334155 !important; }"

