{"title": "Interactive HTML Controls Panel 1 (Radio Buttons, 2 Dropdowns, Checkbox & Slider)", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "autosize": "none",
  "padding": {
    "left": 130,
    "right": 75,
    "top": 5,
    "bottom": 25
  },
  "width": 350,
  "height": 85,
  "params": [
    {
      "name": "OwnerRadio",
      "value": "ALL",
      "bind": {
        "input": "radio",
        "options": [
          "ALL",
          "APPLICATION",
          "PLATFORM",
          "TEST_INFRASTRUCTURE"
        ],
        "name": "Owner (Radio): "
      }
    },
    {
      "name": "CategoryDropdown",
      "value": "ALL",
      "bind": {
        "input": "select",
        "options": [
          "ALL",
          "COMMUNICATION",
          "CAPTURE_ERROR",
          "TIMEOUT",
          "DATA_INTEGRITY",
          "ASSERTION_FAILURE"
        ],
        "name": "Category (Dropdown): "
      }
    },
    {
      "name": "SeverityDropdown",
      "value": "ALL",
      "bind": {
        "input": "select",
        "options": [
          "ALL",
          "CRITICAL",
          "HIGH",
          "MEDIUM",
          "LOW"
        ],
        "name": "Severity (Dropdown): "
      }
    },
    {
      "name": "OnlyMultiRule",
      "value": false,
      "bind": {
        "input": "checkbox",
        "name": "Multi-Faults Only (Checkbox): "
      }
    },
    {
      "name": "MinFaultSlider",
      "value": 1,
      "bind": {
        "input": "range",
        "min": 1,
        "max": 3,
        "step": 1,
        "name": "Min Faults (Slider): "
      }
    }
  ],
  "data": {
    "url": {
      "%context%": true,
      "%timefield%": "@timestamp",
      "index": "xml-insight-testcases-v1*",
      "body": {
        "size": 300,
        "_source": [
          "test_bench.id",
          "suite.name",
          "test_case.name",
          "fault_count",
          "error_mapping"
        ]
      }
    },
    "format": {
      "property": "hits.hits"
    }
  },
  "transform": [
    {
      "filter": "datum._source.error_mapping && datum._source.error_mapping.category"
    },
    {
      "calculate": "datum._source.test_case.name",
      "as": "testcase"
    },
    {
      "calculate": "datum._source.error_mapping.category",
      "as": "category"
    },
    {
      "calculate": "datum._source.error_mapping.owner",
      "as": "owner"
    },
    {
      "calculate": "datum._source.error_mapping.severity",
      "as": "severity"
    },
    {
      "calculate": "datum._source.fault_count || 1",
      "as": "faults"
    },
    {
      "filter": "(OwnerRadio == 'ALL' || datum.owner == OwnerRadio) && (CategoryDropdown == 'ALL' || datum.category == CategoryDropdown) && (SeverityDropdown == 'ALL' || datum.severity == SeverityDropdown) && (!OnlyMultiRule || datum.faults >= 2) && datum.faults >= MinFaultSlider"
    },
    {
      "aggregate": [
        {
          "op": "count",
          "as": "failures"
        }
      ],
      "groupby": [
        "testcase",
        "severity"
      ]
    }
  ],
  "mark": {
    "type": "bar",
    "cornerRadiusEnd": 4,
    "stroke": "#ffffff",
    "strokeWidth": 1
  },
  "encoding": {
    "y": {
      "field": "testcase",
      "type": "nominal",
      "sort": "-x",
      "title": "TestCase"
    },
    "x": {
      "field": "failures",
      "type": "quantitative",
      "title": "Failures"
    },
    "color": {
      "field": "severity",
      "type": "nominal",
      "title": "Severity",
      "scale": {
        "domain": [
          "CRITICAL",
          "HIGH",
          "MEDIUM",
          "LOW"
        ],
        "range": [
          "#dc2626",
          "#f97316",
          "#eab308",
          "#10b981"
        ]
      }
    }
  }
}"}}

